import sqlite3, re
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
def one(s): return con.execute(s).fetchone()[0]

print("## (1) PRAGMA user_version")
print("user_version =", one("PRAGMA user_version"))

tables = [r[0] for r in con.execute("select name from sqlite_master where type='table' order by name")]
views  = [r[0] for r in con.execute("select name from sqlite_master where type='view' order by name")]
counts = {t: one(f'select count(*) from "{t}"') for t in tables}
empty  = sorted(t for t in tables if counts[t] == 0)
emptyset = set(empty)

print(f"\n## (2) row counts, {len(tables)} tables, sorted descending")
for t in sorted(tables, key=lambda t: (-counts[t], t)):
    print(f"{counts[t]:>7}  {t}")
print(f"\nEMPTY tables ({len(empty)}): " + (", ".join(empty) if empty else "[none]"))

print("\n## (3) UNWRITABLE probe (NOT NULL FK column -> parent table with 0 rows)")
unw = 0; nullable_into_empty = 0; dangling = []; pk_nullable = []
for t in tables:
    fks = list(con.execute(f'PRAGMA foreign_key_list("{t}")'))
    for f in fks:
        if f[2] not in set(tables):
            dangling.append(f"{t}.{f[3]} -> {f[2]} (parent not a table)")
    parent_of = {f[3]: f[2] for f in fks if f[2] in emptyset}
    for c in con.execute(f'PRAGMA table_info("{t}")'):
        if c[1] in parent_of:
            if c[3]:
                unw += 1
                print(f"UNWRITABLE {t}.{c[1]} -> {parent_of[c[1]]}")
            else:
                nullable_into_empty += 1
                if c[5]:
                    pk_nullable.append(f"{t}.{c[1]} -> {parent_of[c[1]]}")
print(f"UNWRITABLE total: {unw}")
print(f"context: nullable FK columns into empty tables (writable as NULL): {nullable_into_empty}")
print("dangling FKs (parent name not in sqlite_master tables):", dangling if dangling else "[none]")
print("PK columns that are nullable FKs into empty tables:", pk_nullable if pk_nullable else "[none]")

print(f"\n## views, {len(views)} total (unproven if 0 rows)")
zero_views = []
for v in views:
    try:
        n = one(f'select count(*) from "{v}"')
    except Exception as e:
        n = f"ERROR {e}"
    if n == 0: zero_views.append(v)
    print(f"{n:>7}  {v}")
print("0-row views:", zero_views if zero_views else "[none]")

print("\n## (4) session attribution")
SESS = re.compile(r'^session_(\d{4}-\d{2}-\d{2})-')
sess_cols = []
for t in tables:
    for c in con.execute(f'PRAGMA table_info("{t}")'):
        if c[1].endswith('_session'):
            sess_cols.append((t, c[1]))
def distinct_vals(t, c):
    return [r[0] for r in con.execute(f'select distinct "{c}" from "{t}" where "{c}" is not null')]
nonconf = {}
allsess = set()
for t, c in sess_cols:
    for v in distinct_vals(t, c):
        if isinstance(v, str) and SESS.match(v): allsess.add(v)
        else: nonconf.setdefault(f"{t}.{c}", []).append(v)
key = lambda s: (SESS.match(s).group(1), s)
print("session-like columns scanned:", len(sess_cols))
print("non-conforming values in *_session columns:")
for k, vs in nonconf.items():
    print(f"   {k}: {len(vs)} distinct, e.g. {vs[:3]}")
top_scope = {s for s in set(distinct_vals('evidence_sources','created_by_session')) | set(distinct_vals('search_executions','created_by_session')) if s and SESS.match(s)}
five_scope = sorted(top_scope, key=key, reverse=True)[:5]
five_all = sorted(allsess, key=key, reverse=True)[:5]
print("FIVE MOST RECENT (evidence_sources + search_executions created_by_session):", five_scope)
print("FIVE MOST RECENT (all *_session columns, all tables):", five_all)

def cnt(t, c, s): return one(f'select count(*) from "{t}" where "{c}" = \'{s}\'')
for s in five_scope:
    print(f"\n### {s}")
    print(f"   evidence_sources.created_by_session: {cnt('evidence_sources','created_by_session',s)}")
    print(f"   search_executions.created_by_session: {cnt('search_executions','created_by_session',s)}")
    print("   all tables, nonzero:")
    for t, c in sess_cols:
        n = cnt(t, c, s)
        if n: print(f"      {n:>5}  {t}.{c}")
